using System;
using System.Linq;
using System.Net;

namespace UI_Desktop.Store;

internal static class StoreFix54Html
{
	internal static string Styles => ".fix54-button { min-height:44px; touch-action:manipulation; }\r\nbody.fix54-modal-open { overflow:hidden; }\r\n[data-fix54-overlay] { z-index:10010; }\r\n[data-fix54-overlay][hidden], [data-fix54-cancel][hidden], [data-fix54-close][hidden], [data-fix54-loader][hidden], [data-fix54-progress][hidden], [data-fix54-percent][hidden] { display:none; }\r\n[data-fix54-dialog] .activation-title-block { overflow-wrap:anywhere; }\r\n[data-fix54-dialog] .fix54-status { margin:8px 0; color:#eaf7ff; font-size:14px; line-height:1.5; overflow-wrap:anywhere; }\r\n[data-fix54-dialog] .activation-summary { overflow-wrap:anywhere; }\r\n[data-fix54-dialog] .activation-actions button { min-height:44px; touch-action:manipulation; }\r\n[data-fix54-dialog] button:focus-visible { outline:2px solid var(--activation-accent-strong); outline-offset:3px; }\r\n[data-fix54-dialog]:focus-visible { outline:2px solid var(--activation-accent-strong); outline-offset:3px; }\r\n@media (prefers-reduced-motion:reduce) { [data-fix54-dialog] *, [data-fix54-dialog] *::before, [data-fix54-dialog] *::after { animation:none!important; transition:none!important; } }";

	internal static string Script => "(() => {\r\n    const revisions = new WeakMap();\r\n    const peerSelector = 'button[data-action=\"play\"],button[data-action=\"cloudsave:open\"],button[data-action^=\"denuvo:\"],button[data-action^=\"pypass:\"],button[data-action^=\"online:\"],button[data-action=\"cloudredirect:manage\"]';\r\n    let activeButton = null;\r\n    let peerStates = null;\r\n    let peerObserver = null;\r\n    let overlay = null;\r\n    let modalButton = null;\r\n    let modalRunning = false;\r\n    let cancelRequested = false;\r\n    let lastPercentage = null;\r\n    let previousFocus = null;\r\n    let backgroundStates = null;\r\n    let backgroundObserver = null;\r\n    let redirectingFocus = false;\r\n    const isFocusable = element => element instanceof HTMLElement && element.isConnected && !element.hidden &&\r\n        !element.disabled && !element.closest('[inert]') && element.getClientRects().length > 0;\r\n    const focusModal = () => {\r\n        if (!overlay || overlay.hidden) return;\r\n        const target = [...overlay.querySelectorAll('button')].find(isFocusable) || overlay.querySelector('[data-fix54-dialog]');\r\n        target?.focus();\r\n    };\r\n    const freezeBackground = () => {\r\n        if (backgroundStates) return;\r\n        backgroundStates = new Map();\r\n        const freeze = child => {\r\n            if (!(child instanceof HTMLElement) || child === overlay || ['SCRIPT','STYLE','LINK'].includes(child.tagName)) return;\r\n            if (!backgroundStates.has(child)) backgroundStates.set(child, child.inert);\r\n            child.inert = true;\r\n        };\r\n        for (const child of document.body.children) freeze(child);\r\n        backgroundObserver = new MutationObserver(records => {\r\n            for (const record of records) for (const child of record.addedNodes) freeze(child);\r\n        });\r\n        backgroundObserver.observe(document.body, {childList:true});\r\n    };\r\n    const unfreezeBackground = () => {\r\n        backgroundObserver?.disconnect();\r\n        if (backgroundStates) for (const [child, wasInert] of backgroundStates) if (child.isConnected) child.inert = wasInert;\r\n        backgroundStates = null;\r\n        backgroundObserver = null;\r\n    };\r\n    const closeModal = (force = false) => {\r\n        if (!overlay || overlay.hidden || (modalRunning && !force)) return false;\r\n        overlay.hidden = true;\r\n        unfreezeBackground();\r\n        document.body.classList.remove('fix54-modal-open');\r\n        const target = isFocusable(modalButton) ? modalButton : isFocusable(previousFocus) ? previousFocus : null;\r\n        target?.focus();\r\n        return true;\r\n    };\r\n    const ensureModal = button => {\r\n        if (overlay) return overlay;\r\n        overlay = document.createElement('div');\r\n        overlay.className = 'activation-overlay fix54-overlay';\r\n        overlay.setAttribute('data-fix54-overlay','');\r\n        overlay.hidden = true;\r\n        overlay.innerHTML = `\r\n<section class=\"activation-dialog fix54-dialog\" data-fix54-dialog role=\"dialog\" aria-modal=\"true\" tabindex=\"-1\">\r\n    <header class=\"activation-hero\">\r\n        <div class=\"activation-mark\" aria-hidden=\"true\"><span class=\"activation-status-symbol\" data-fix54-symbol>...</span></div>\r\n        <div class=\"activation-title-block\"><h2 class=\"activation-title\" data-fix54-title>FIX 54</h2><p class=\"activation-summary\" data-fix54-summary></p></div>\r\n    </header>\r\n    <div class=\"activation-content\"><div class=\"activation-main-column\">\r\n        <div class=\"activation-loader\" data-fix54-loader hidden>\r\n            <span class=\"activation-loader-spinner\" aria-hidden=\"true\"></span>\r\n            <div class=\"activation-loader-body\"><div class=\"activation-loader-heading\"><strong data-fix54-loader-text></strong><b class=\"activation-loader-percent\" data-fix54-percent hidden></b></div>\r\n                <div class=\"activation-progress-track\" data-fix54-progress role=\"progressbar\" aria-label=\"Tiến độ FIX 54\" aria-valuemin=\"0\" aria-valuemax=\"100\" hidden><i class=\"activation-progress-fill\" data-fix54-progress-fill></i></div>\r\n            </div>\r\n        </div>\r\n        <p class=\"fix54-status\" data-fix54-status role=\"status\" aria-live=\"polite\" aria-atomic=\"true\"></p>\r\n    </div></div>\r\n    <footer class=\"activation-actions\"><button type=\"button\" class=\"activation-primary-button\" data-fix54-cancel hidden disabled>Hủy</button><button type=\"button\" class=\"activation-close-button\" data-fix54-close hidden disabled>Đóng</button></footer>\r\n</section>`;\r\n        const libraryId = button.dataset.fix54LibraryId;\r\n        const dialog = overlay.querySelector('[data-fix54-dialog]');\r\n        dialog.id = 'fix54-dialog-' + libraryId;\r\n        dialog.setAttribute('aria-labelledby','fix54-title-' + libraryId);\r\n        dialog.setAttribute('aria-describedby','fix54-status-' + libraryId);\r\n        overlay.querySelector('[data-fix54-title]').id = 'fix54-title-' + libraryId;\r\n        overlay.querySelector('[data-fix54-status]').id = 'fix54-status-' + libraryId;\r\n        overlay.addEventListener('click', event => {\r\n            const target = event.target instanceof Element ? event.target : null;\r\n            if (!target) return;\r\n            if (target.closest('[data-fix54-cancel]')) {\r\n                event.preventDefault(); event.stopPropagation();\r\n                if (!modalRunning || cancelRequested || !modalButton || modalButton.dataset.fix54CanRun !== 'true') return;\r\n                cancelRequested = true;\r\n                updateModal(modalButton, {state:'loading',isCancelling:true,progressPercentage:lastPercentage}, true,\r\n                    'Đang hủy và khôi phục file gốc. Vui lòng chờ hoàn tất.');\r\n                window.chrome?.webview?.postMessage('fix54:cancel:' + modalButton.dataset.fix54LibraryId + ':' + modalButton.dataset.fix54DocumentId);\r\n            } else if (target.closest('[data-fix54-close]') || target === overlay) {\r\n                event.preventDefault(); event.stopPropagation(); closeModal();\r\n            }\r\n        });\r\n        document.body.append(overlay);\r\n        return overlay;\r\n    };\r\n    const updateModal = (button, payload, running, message) => {\r\n        const modal = ensureModal(button);\r\n        const opening = modal.hidden;\r\n        const wasRunning = modalRunning;\r\n        if (opening) {\r\n            previousFocus = document.activeElement;\r\n            cancelRequested = false;\r\n        }\r\n        if (running && !wasRunning) cancelRequested = false;\r\n        cancelRequested = running && (cancelRequested || payload.isCancelling === true);\r\n        modalButton = button;\r\n        modalRunning = running;\r\n        const state = running ? 'loading' : ['success','warning','error'].includes(payload.state) ? payload.state : 'warning';\r\n        const dialog = modal.querySelector('[data-fix54-dialog]');\r\n        dialog.className = 'activation-dialog fix54-dialog is-' + state;\r\n        dialog.setAttribute('aria-busy',String(running));\r\n        modal.querySelector('[data-fix54-title]').textContent = running ? cancelRequested ? 'Đang hủy FIX 54' : 'Đang xử lý FIX 54' :\r\n            state === 'success' ? 'FIX 54 hoàn tất' : state === 'error' ? 'Không thể chạy FIX 54' : 'Thông báo FIX 54';\r\n        modal.querySelector('[data-fix54-summary]').textContent = [button.dataset.fix54GameName,button.dataset.fix54Version].filter(Boolean).join(' · ');\r\n        modal.querySelector('[data-fix54-symbol]').textContent = running ? '...' : state === 'success' ? '✓' : '!';\r\n        modal.querySelector('[data-fix54-status]').textContent = message || 'Đang xử lý FIX 54...';\r\n        const percentage = !cancelRequested && Number.isInteger(payload.progressPercentage) && payload.progressPercentage >= 0 && payload.progressPercentage <= 100 ? payload.progressPercentage : null;\r\n        lastPercentage = percentage;\r\n        const loader = modal.querySelector('[data-fix54-loader]');\r\n        loader.hidden = !running;\r\n        loader.classList.toggle('has-progress', running && percentage !== null);\r\n        modal.querySelector('[data-fix54-loader-text]').textContent = cancelRequested ? 'Đang hủy và khôi phục...' : 'Đang xử lý FIX 54...';\r\n        const percent = modal.querySelector('[data-fix54-percent]');\r\n        percent.hidden = percentage === null;\r\n        percent.textContent = percentage === null ? '' : percentage + '%';\r\n        const progress = modal.querySelector('[data-fix54-progress]');\r\n        progress.hidden = percentage === null;\r\n        if (percentage === null) progress.removeAttribute('aria-valuenow');\r\n        else progress.setAttribute('aria-valuenow',String(percentage));\r\n        modal.querySelector('[data-fix54-progress-fill]').style.width = percentage === null ? '0%' : percentage + '%';\r\n        const cancel = modal.querySelector('[data-fix54-cancel]');\r\n        cancel.hidden = !running;\r\n        cancel.disabled = !running || cancelRequested;\r\n        cancel.setAttribute('aria-disabled',String(cancel.disabled));\r\n        cancel.textContent = cancelRequested ? 'Đang hủy...' : 'Hủy';\r\n        const close = modal.querySelector('[data-fix54-close]');\r\n        close.hidden = running;\r\n        close.disabled = running;\r\n        close.setAttribute('aria-disabled',String(running));\r\n        modal.hidden = false;\r\n        freezeBackground();\r\n        document.body.classList.add('fix54-modal-open');\r\n        if (opening || (wasRunning && !running) || (!isFocusable(document.activeElement) && modal.contains(document.activeElement))) focusModal();\r\n    };\r\n    window.addEventListener('keydown', event => {\r\n        if (!overlay || overlay.hidden) return;\r\n        if (event.key === 'Escape') {\r\n            event.preventDefault(); event.stopImmediatePropagation(); closeModal();\r\n        } else if (event.key === 'Tab') {\r\n            event.preventDefault(); event.stopImmediatePropagation(); focusModal();\r\n        }\r\n    }, true);\r\n    document.addEventListener('focusin', event => {\r\n        if (!overlay || overlay.hidden || overlay.contains(event.target) || redirectingFocus) return;\r\n        event.stopImmediatePropagation();\r\n        redirectingFocus = true;\r\n        focusModal();\r\n        redirectingFocus = false;\r\n    }, true);\r\n    const lockPeers = button => {\r\n        if (activeButton === button && peerStates) return;\r\n        activeButton = button;\r\n        peerStates = new Map([...document.querySelectorAll(peerSelector)].map(peer => [peer, {\r\n            disabled: peer.disabled,\r\n            ariaDisabled: peer.getAttribute('aria-disabled'),\r\n            wasCooldown: peer.hasAttribute('data-denuvo-cooldown-until')\r\n        }]));\r\n        const enforceDisabled = () => {\r\n            if (!activeButton?.isConnected) return;\r\n            for (const peer of peerStates.keys()) {\r\n                if (!peer.isConnected) continue;\r\n                if (!peer.disabled) peer.disabled = true;\r\n                if (peer.getAttribute('aria-disabled') !== 'true') peer.setAttribute('aria-disabled', 'true');\r\n            }\r\n        };\r\n        enforceDisabled();\r\n        peerObserver = new MutationObserver(enforceDisabled);\r\n        for (const peer of peerStates.keys()) peerObserver.observe(peer, {attributes:true,attributeFilter:['disabled','aria-disabled']});\r\n    };\r\n    const restorePeers = button => {\r\n        if (activeButton !== button || !peerStates) return;\r\n        peerObserver?.disconnect();\r\n        for (const [peer, prior] of peerStates) {\r\n            if (!peer.isConnected) continue;\r\n            const cooldownExpired = prior.wasCooldown && !peer.hasAttribute('data-denuvo-cooldown-until') &&\r\n                peer.getAttribute('data-denuvo-locked') !== 'true';\r\n            const locked = ['data-denuvo-locked','data-pypass-locked','data-online-locked'].some(name => peer.getAttribute(name) === 'true') ||\r\n                peer.classList.contains('is-loading') || peer.getAttribute('aria-busy') === 'true';\r\n            peer.disabled = locked || (prior.disabled && !cooldownExpired);\r\n            if (peer.disabled) peer.setAttribute('aria-disabled', 'true');\r\n            else if (prior.ariaDisabled === null) peer.removeAttribute('aria-disabled');\r\n            else peer.setAttribute('aria-disabled', 'false');\r\n        }\r\n        activeButton = null;\r\n        peerStates = null;\r\n        peerObserver = null;\r\n    };\r\n    document.addEventListener('click', event => {\r\n        if (!activeButton?.isConnected || activeButton.getAttribute('aria-busy') !== 'true') return;\r\n        const peer = event.target instanceof Element ? event.target.closest(peerSelector) : null;\r\n        if (!peer) return;\r\n        event.preventDefault();\r\n        event.stopImmediatePropagation();\r\n    }, true);\r\n    const normalizeLibraryId = value => {\r\n        if (typeof value !== 'string') return '';\r\n        if (!/^[a-f0-9]{32}$/i.test(value) && !/^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$/i.test(value)) return '';\r\n        const compact = value.replaceAll('-', '').toLowerCase();\r\n        return /^[a-f0-9]{32}$/.test(compact) ? compact : '';\r\n    };\r\n    window.setFix54State = payload => {\r\n        if (!payload || typeof payload.documentId !== 'string' || typeof payload.isRunning !== 'boolean') return false;\r\n        const libraryId = normalizeLibraryId(payload.libraryId);\r\n        if (!libraryId) return false;\r\n        const button = [...document.querySelectorAll('[data-fix54-button]')].find(candidate =>\r\n            candidate.dataset.fix54DocumentId === payload.documentId && candidate.dataset.fix54LibraryId === libraryId);\r\n        if (!button || !button.isConnected) return false;\r\n        if (payload.revision !== undefined && payload.revision !== null) {\r\n            if (!Number.isSafeInteger(payload.revision) || payload.revision < 0 ||\r\n                payload.revision <= (revisions.get(button) ?? -1)) return false;\r\n            revisions.set(button, payload.revision);\r\n        }\r\n        const canRun = button.dataset.fix54CanRun === 'true';\r\n        const running = payload.isRunning && canRun;\r\n        button.disabled = running || !canRun;\r\n        button.classList.toggle('is-loading', running);\r\n        button.setAttribute('aria-disabled', String(button.disabled));\r\n        button.setAttribute('aria-busy', String(running));\r\n        button.textContent = running ? 'ĐANG FIX...' : 'FIX 54';\r\n        if (running) lockPeers(button);\r\n        else restorePeers(button);\r\n        const message = typeof payload.message === 'string' ? payload.message.slice(0,2048) : '';\r\n        if (!running && !message.trim()) { modalRunning = false; closeModal(true); }\r\n        else updateModal(button, payload, running, message);\r\n        return true;\r\n    };\r\n    for (const button of document.querySelectorAll('[data-fix54-button]')) {\r\n        ensureModal(button);\r\n        if (button.getAttribute('aria-busy') === 'true' && button.dataset.fix54CanRun === 'true') {\r\n            lockPeers(button); updateModal(button, {state:'loading'}, true, 'Đang xử lý FIX 54...');\r\n        }\r\n    }\r\n})();";

	internal static string BuildButton(DesktopLibraryDetailResponse detail, string documentId, bool isRunning, bool steamStyle)
	{
		ArgumentNullException.ThrowIfNull(detail, "detail");
		bool flag = CanRun(detail, documentId);
		string value = detail.LibraryId.ToString("N");
		string value2 = (flag ? $" data-action=\"fix54:run:{value}:{Encode(documentId)}\"" : string.Empty);
		bool flag2 = isRunning || !flag;
		string value3 = (steamStyle ? "steam-cloud-button" : "library-button");
		return $"<button type=\"button\" class=\"{value3} fix54-button{(isRunning ? " is-loading" : string.Empty)}\" data-fix54-button\r\n    data-fix54-document-id=\"{Encode(documentId)}\" data-fix54-library-id=\"{value}\" data-fix54-can-run=\"{Boolean(flag)}\"\r\n    data-fix54-game-name=\"{Encode(detail.GameName)}\" data-fix54-version=\"{Encode(detail.VersionName)}\"\r\n    data-default-label=\"FIX 54\"{value2}{(flag2 ? " disabled" : string.Empty)} aria-disabled=\"{Boolean(flag2)}\" aria-busy=\"{Boolean(isRunning)}\"\r\n    aria-haspopup=\"dialog\" aria-controls=\"fix54-dialog-{value}\">{(isRunning ? "ĐANG FIX..." : "FIX 54")}</button>";
	}

	private static bool CanRun(DesktopLibraryDetailResponse detail, string documentId)
	{
		int? steamAppId = detail.SteamAppId;
		if (steamAppId.HasValue && steamAppId.GetValueOrDefault() > 0 && detail.LibraryId != Guid.Empty && !string.IsNullOrEmpty(documentId) && documentId.Length <= 128)
		{
			return documentId.All(delegate(char character)
			{
				bool flag = char.IsAsciiLetterOrDigit(character);
				if (!flag)
				{
					bool flag2 = ((character == '-' || character == '_') ? true : false);
					flag = flag2;
				}
				return flag;
			});
		}
		return false;
	}

	private static string Boolean(bool value)
	{
		if (!value)
		{
			return "false";
		}
		return "true";
	}

	private static string Encode(string? value)
	{
		return WebUtility.HtmlEncode(value ?? string.Empty);
	}
}
